string memory _name,
string memory _symbol,
address _erc721,
address _feeTo
) ERC20(_name, _symbol) {
_mint(msg.sender, 260000000 * 10 ** 18);
erc721 = _erc721;
feeTo = _feeTo;
owner = msg.sender;
}

